import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';

function App() {
  const [user, setUser] = useState(null);
  const [page, setPage] = useState('login');
  const [emailInput, setEmailInput] = useState('');
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [editingItem, setEditingItem] = useState(null);
  const [formData, setFormData] = useState({});
  const [courses, setCourses] = useState([]);
  const [assignments, setAssignments] = useState([]);
  const [enrolledCourseIds, setEnrolledCourseIds] = useState([]);
  const [selectedAssignment, setSelectedAssignment] = useState(null);
  const [submissionText, setSubmissionText] = useState('');
  const [showFileModal, setShowFileModal] = useState(false);
  const [currentSubmissionText, setCurrentSubmissionText] = useState('');
  const [showGradeModal, setShowGradeModal] = useState(false);
  const [submissionToGrade, setSubmissionToGrade] = useState(null);
  const [gradeValue, setGradeValue] = useState('');
  const [feedbackText, setFeedbackText] = useState('');
  const [showConfirmDelete, setShowConfirmDelete] = useState(false);
  const [itemToDelete, setItemToDelete] = useState(null);
  const [deleteBase, setDeleteBase] = useState('');
  const [allUsers, setAllUsers] = useState([]);
  const [showChat, setShowChat] = useState(false);
  const [chatMessages, setChatMessages] = useState([
    { sender: 'bot', text: "Hello! I'm your Student Portal assistant. Ask me anything about how to use the portal!" }
  ]);
  const [chatInput, setChatInput] = useState('');
  const [chatLoading, setChatLoading] = useState(false);
  const chatEndRef = useRef(null);

  const API = 'http://localhost:5000/api';

  const getEndpoint = (pageName) => {
    if (pageName === 'students') return user?.role === 'instructor' ? `courses?instructorid=${user.id}` : 'courses';
    if (pageName === 'courses') return 'courses';
    if (pageName === 'assignments') return 'assignments';
    if (pageName === 'announcements') return 'announcements';
    if (pageName === 'submissions') return user?.role === 'student' ? `submissions?studentid=${user.id}` : 'submissions';
    if (pageName === 'instructors') return 'users?role=instructor';
    return null;
  };

  const getEmptyForm = (pageName) => {
    if (pageName === 'assignments') return { title: '', duedate: '', description: '', courseid: '' };
    if (pageName === 'announcements') return { title: '', message: '', courseid: '' };
    if (pageName === 'instructors') return { name: '', email: '', courseTitle: '', courseDescription: '', courseSyllabus: '' };
    return {};
  };

  const login = async (e) => {
    e.preventDefault();
    if (!emailInput.trim()) return alert('Please enter your email');
    try {
      const res = await axios.post(`${API}/users/login`, { email: emailInput.trim() });
      setUser(res.data);
      setPage(res.data.role === 'admin' ? 'instructors' : res.data.role === 'instructor' ? 'students' : 'courses');
    } catch (err) {
      alert('Login failed — user not found');
    }
  };

  const logout = () => {
    setUser(null);
    setPage('login');
    setEmailInput('');
    setData([]);
    setCourses([]);
    setAssignments([]);
    setEnrolledCourseIds([]);
  };

  const changePage = (newPage) => {
    setPage(newPage);
    setShowForm(false);
    setEditingItem(null);
    setFormData(getEmptyForm(newPage));
  };

  const fetchData = async (endpoint) => {
    setLoading(true);
    try {
      const res = await axios.get(`${API}/${endpoint}`);
      setData(res.data);
    } catch (err) {
      alert('Error fetching data');
    }
    setLoading(false);
  };

  useEffect(() => {
    if (user) {
      const endpoint = getEndpoint(page);
      if (endpoint) fetchData(endpoint);
      if (page === 'courses' || page === 'students') {
        fetchData('courses');
      }
      if (page === 'assignments') {
        fetchData('assignments');
      }
      if (user.role === 'admin') {
        axios.get(`${API}/users`).then(res => setAllUsers(res.data));
      }
    }
  }, [page, user]);

  useEffect(() => {
    if (data.length && (page === 'courses' || page === 'students')) {
      setCourses(data);
      if (user?.role === 'student') {
        setEnrolledCourseIds(data.filter(c => c.students?.includes(user.id)).map(c => c.id));
      }
    }
    if (data.length && page === 'assignments') {
      setAssignments(data);
    }
  }, [data]);

  const handleFormChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleCreateOrUpdate = async (base) => {
    try {
      if (editingItem) {
        await axios.put(`${API}/${base}/${editingItem.id}`, formData);
      } else {
        await axios.post(`${API}/${base}`, formData);
      }
      fetchData(getEndpoint(page));
      setShowForm(false);
      setEditingItem(null);
    } catch (err) {
      alert('Error saving');
    }
  };

  const startEdit = (item) => {
    setFormData(item);
    setEditingItem(item);
    setShowForm(true);
  };

  const confirmDelete = (item, base) => {
    setItemToDelete(item);
    setDeleteBase(base);
    setShowConfirmDelete(true);
  };

  const handleDelete = async () => {
    try {
      await axios.delete(`${API}/${deleteBase}/${itemToDelete.id}`);
      fetchData(getEndpoint(page));
    } catch (err) {
      alert('Error deleting');
    }
    setShowConfirmDelete(false);
    setItemToDelete(null);
    setDeleteBase('');
  };

  const handleEnroll = async (courseId) => {
    try {
      await axios.post(`${API}/courses/${courseId}/enroll`, { studentid: user.id });
      fetchData('courses');
    } catch (err) {
      alert('Error enrolling');
    }
  };

  const handleDrop = async (courseId) => {
    try {
      await axios.post(`${API}/courses/${courseId}/drop`, { studentid: user.id });
      fetchData('courses');
    } catch (err) {
      alert('Error dropping');
    }
  };

  const selectAssignmentForSubmit = (assignment) => {
    setSelectedAssignment(assignment);
    setSubmissionText('');
  };

  const submitAssignment = async () => {
    if (!submissionText.trim()) return alert('Please enter submission text');
    try {
      await axios.post(`${API}/submissions`, {
        assignmentid: selectedAssignment.id,
        studentid: user.id,
        fileurl: submissionText,  // Using text as "file" for demo
      });
      alert('Submitted!');
      setSelectedAssignment(null);
      setSubmissionText('');
      if (page === 'submissions') fetchData('submissions');
    } catch (err) {
      alert('Error submitting');
    }
  };

  const viewSubmission = (text) => {
    setCurrentSubmissionText(text);
    setShowFileModal(true);
  };

  const startGrading = (submission) => {
    setSubmissionToGrade(submission);
    setGradeValue(submission.grade || '');
    setFeedbackText(submission.feedback || '');
    setShowGradeModal(true);
  };

  const submitGrade = async () => {
    try {
      await axios.put(`${API}/submissions/${submissionToGrade.id}/grade`, {
        grade: gradeValue,
        feedback: feedbackText,
      });
      fetchData('submissions');
      setShowGradeModal(false);
      setSubmissionToGrade(null);
    } catch (err) {
      alert('Error grading');
    }
  };

  const handleAdminAddInstructor = async () => {
    try {
      const instructorRes = await axios.post(`${API}/users`, {
        name: formData.name,
        email: formData.email,
        role: 'instructor',
      });
      const instructorId = instructorRes.data.id;

      await axios.post(`${API}/courses`, {
        title: formData.courseTitle,
        description: formData.courseDescription,
        syllabus: formData.courseSyllabus,
        instructorid: instructorId,
      });

      fetchData('users?role=instructor');
      setShowForm(false);
    } catch (err) {
      alert('Error adding instructor/course');
    }
  };

  const sendChatMessage = async () => {
    if (!chatInput.trim()) return;
    setChatMessages([...chatMessages, { sender: 'user', text: chatInput }]);
    setChatLoading(true);
    try {
      const res = await axios.post(`${API}/chat`, { message: chatInput });
      setChatMessages(msgs => [...msgs, { sender: 'bot', text: res.data.reply }]);
    } catch (err) {
      setChatMessages(msgs => [...msgs, { sender: 'bot', text: 'Sorry, error occurred.' }]);
    }
    setChatLoading(false);
    setChatInput('');
  };

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatMessages]);

  if (!user) {
    return (
      <div style={{ maxWidth: '400px', margin: '100px auto', textAlign: 'center' }}>
        <h1>Student Portal Login</h1>
        <form onSubmit={login}>
          <input
            type="email"
            value={emailInput}
            onChange={(e) => setEmailInput(e.target.value)}
            placeholder="Enter your email"
            style={{ width: '100%', padding: '15px', margin: '10px 0', borderRadius: '8px', border: '1px solid #ddd' }}
            required
          />
          <button type="submit" style={{ width: '100%', padding: '15px', background: '#667eea', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>Login</button>
        </form>
        <p style={{ marginTop: '20px' }}>Demo emails: nm@sportal.com (student), mc@sportal.com (instructor), admin@sportal.com (admin)</p>
      </div>
    );
  }

  return (
    <div>
      <>
        <nav style={{ background: '#333', padding: '15px', textAlign: 'center' }}>
          {user.role === 'admin' ? (
            <>
              <a href="#" onClick={() => changePage('instructors')}>Manage Instructors</a>
              <a href="#" onClick={() => changePage('courses')}>Manage Courses</a>
            </>
          ) : user.role === 'instructor' ? (
            <>
              <a href="#" onClick={() => changePage('students')}>My Courses</a>
              <a href="#" onClick={() => changePage('assignments')}>Assignments</a>
              <a href="#" onClick={() => changePage('announcements')}>Announcements</a>
              <a href="#" onClick={() => changePage('submissions')}>Submissions</a>
            </>
          ) : (
            <>
              <a href="#" onClick={() => changePage('courses')}>Courses</a>
              <a href="#" onClick={() => changePage('assignments')}>Assignments</a>
              <a href="#" onClick={() => changePage('announcements')}>Announcements</a>
              <a href="#" onClick={() => changePage('submissions')}>My Submissions</a>
            </>
          )}
          <a href="#" onClick={() => setShowChat(true)}>AI Help</a>
          <a href="#" onClick={logout} style={{ float: 'right', marginRight: '20px' }}>Logout</a>
        </nav>
        <main>
          <div className="container">
            <h1>Welcome, {user.name} ({user.role})</h1>

            {loading && <p>Loading...</p>}

            {/* Courses / Students Page */}
            {(page === 'courses' || page === 'students') && (
              <>
                <h2>{page === 'students' ? 'My Courses & Students' : 'Available Courses'}</h2>
                {user.role === 'instructor' && page === 'students' && (
                  <button onClick={() => { setShowForm(true); setFormData({ title: '', description: '', syllabus: '' }); }} className="btn">Add Course</button>
                )}
                <table>
                  <thead>
                    <tr>
                      <th>Title</th>
                      <th>Description</th>
                      <th>Syllabus</th>
                      {page === 'students' && <th>Students</th>}
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {courses.map(course => (
                      <tr key={course.id}>
                        <td>{course.title}</td>
                        <td>{course.description}</td>
                        <td>{course.syllabus}</td>
                        {page === 'students' && <td>{course.students?.join(', ') || 'None'}</td>}
                        <td>
                          {user.role === 'student' && (
                            enrolledCourseIds.includes(course.id) ? (
                              <button onClick={() => handleDrop(course.id)} className="btn" style={{ background: '#e53e3e' }}>Drop</button>
                            ) : (
                              <button onClick={() => handleEnroll(course.id)} className="btn">Enroll</button>
                            )
                          )}
                          {(user.role === 'instructor' && course.instructorid === user.id) || user.role === 'admin' ? (
                            <>
                              <button onClick={() => startEdit(course)} className="btn">Edit</button>
                              <button onClick={() => confirmDelete(course, 'courses')} className="btn" style={{ background: '#e53e3e' }}>Delete</button>
                            </>
                          ) : null}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>

                {showForm && (
                  <>
                    <h3>{editingItem ? 'Edit Course' : 'Add Course'}</h3>
                    <form onSubmit={(e) => { e.preventDefault(); handleCreateOrUpdate('courses'); }}>
                      <input name="title" value={formData.title} onChange={handleFormChange} placeholder="Title" required style={{ display: 'block', margin: '10px 0', padding: '10px', width: '100%' }} />
                      <textarea name="description" value={formData.description} onChange={handleFormChange} placeholder="Description" style={{ display: 'block', margin: '10px 0', padding: '10px', width: '100%' }} />
                      <textarea name="syllabus" value={formData.syllabus} onChange={handleFormChange} placeholder="Syllabus" style={{ display: 'block', margin: '10px 0', padding: '10px', width: '100%' }} />
                      <button type="submit" className="btn">Save</button>
                      <button type="button" onClick={() => setShowForm(false)} className="btn" style={{ background: '#718096' }}>Cancel</button>
                    </form>
                  </>
                )}
              </>
            )}

            {/* Assignments Page */}
            {page === 'assignments' && (
              <>
                <h2>Assignments</h2>
                {user.role === 'instructor' && <button onClick={() => { setShowForm(true); setFormData(getEmptyForm('assignments')); }} className="btn">Add Assignment</button>}
                <table>
                  <thead>
                    <tr>
                      <th>Title</th>
                      <th>Due Date</th>
                      <th>Description</th>
                      <th>Course ID</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {assignments
                      .filter(a => user.role === 'student' ? enrolledCourseIds.includes(a.courseid) : true)
                      .map(assignment => (
                        <tr key={assignment.id}>
                          <td>{assignment.title}</td>
                          <td>{assignment.duedate}</td>
                          <td>{assignment.description}</td>
                          <td>{assignment.courseid}</td>
                          <td>
                            {user.role === 'instructor' && (
                              <>
                                <button onClick={() => startEdit(assignment)} className="btn">Edit</button>
                                <button onClick={() => confirmDelete(assignment, 'assignments')} className="btn" style={{ background: '#e53e3e' }}>Delete</button>
                              </>
                            )}
                            {user.role === 'student' && (
                              <button onClick={() => selectAssignmentForSubmit(assignment)} className="btn">Submit</button>
                            )}
                          </td>
                        </tr>
                      ))}
                  </tbody>
                </table>

                {showForm && (
                  <>
                    <h3>{editingItem ? 'Edit Assignment' : 'Add Assignment'}</h3>
                    <form onSubmit={(e) => { e.preventDefault(); handleCreateOrUpdate('assignments'); }}>
                      <input name="title" value={formData.title} onChange={handleFormChange} placeholder="Title" required style={{ display: 'block', margin: '10px 0', padding: '10px', width: '100%' }} />
                      <input name="duedate" type="date" value={formData.duedate} onChange={handleFormChange} required style={{ display: 'block', margin: '10px 0', padding: '10px', width: '100%' }} />
                      <textarea name="description" value={formData.description} onChange={handleFormChange} placeholder="Description" style={{ display: 'block', margin: '10px 0', padding: '10px', width: '100%' }} />
                      <select name="courseid" value={formData.courseid} onChange={handleFormChange} required style={{ display: 'block', margin: '10px 0', padding: '10px', width: '100%' }}>
                        <option value="">Select Course</option>
                        {courses.filter(c => c.instructorid === user.id).map(c => <option key={c.id} value={c.id}>{c.title}</option>)}
                      </select>
                      <button type="submit" className="btn">Save</button>
                      <button type="button" onClick={() => setShowForm(false)} className="btn" style={{ background: '#718096' }}>Cancel</button>
                    </form>
                  </>
                )}

                {selectedAssignment && (
                  <div style={{ marginTop: '30px' }}>
                    <h3>Submit for {selectedAssignment.title}</h3>
                    <textarea
                      value={submissionText}
                      onChange={(e) => setSubmissionText(e.target.value)}
                      placeholder="Enter your submission text here (demo as file)"
                      style={{ display: 'block', margin: '10px 0', padding: '10px', width: '100%', height: '150px' }}
                    />
                    <button onClick={submitAssignment} className="btn">Submit</button>
                    <button onClick={() => setSelectedAssignment(null)} className="btn" style={{ background: '#718096' }}>Cancel</button>
                  </div>
                )}
              </>
            )}

            {/* Announcements Page */}
            {page === 'announcements' && (
              <>
                <h2>Announcements</h2>
                {user.role === 'instructor' && <button onClick={() => { setShowForm(true); setFormData(getEmptyForm('announcements')); }} className="btn">Add Announcement</button>}
                <table>
                  <thead>
                    <tr>
                      <th>Title</th>
                      <th>Message</th>
                      <th>Course ID</th>
                      <th>Date</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {data
                      .filter(a => user.role === 'student' ? enrolledCourseIds.includes(a.courseid) : true)
                      .map(ann => (
                        <tr key={ann.id}>
                          <td>{ann.title}</td>
                          <td>{ann.message}</td>
                          <td>{ann.courseid}</td>
                          <td>{ann.dateposted}</td>
                          <td>
                            {user.role === 'instructor' && (
                              <>
                                <button onClick={() => startEdit(ann)} className="btn">Edit</button>
                                <button onClick={() => confirmDelete(ann, 'announcements')} className="btn" style={{ background: '#e53e3e' }}>Delete</button>
                              </>
                            )}
                          </td>
                        </tr>
                      ))}
                  </tbody>
                </table>

                {showForm && (
                  <>
                    <h3>{editingItem ? 'Edit Announcement' : 'Add Announcement'}</h3>
                    <form onSubmit={(e) => { e.preventDefault(); handleCreateOrUpdate('announcements'); }}>
                      <input name="title" value={formData.title} onChange={handleFormChange} placeholder="Title" required style={{ display: 'block', margin: '10px 0', padding: '10px', width: '100%' }} />
                      <textarea name="message" value={formData.message} onChange={handleFormChange} placeholder="Message" required style={{ display: 'block', margin: '10px 0', padding: '10px', width: '100%' }} />
                      <select name="courseid" value={formData.courseid} onChange={handleFormChange} required style={{ display: 'block', margin: '10px 0', padding: '10px', width: '100%' }}>
                        <option value="">Select Course</option>
                        {courses.filter(c => c.instructorid === user.id).map(c => <option key={c.id} value={c.id}>{c.title}</option>)}
                      </select>
                      <button type="submit" className="btn">Save</button>
                      <button type="button" onClick={() => setShowForm(false)} className="btn" style={{ background: '#718096' }}>Cancel</button>
                    </form>
                  </>
                )}
              </>
            )}

            {/* Submissions Page */}
            {page === 'submissions' && (
              <>
                <h2>{user.role === 'student' ? 'My Submissions' : 'Student Submissions'}</h2>
                <table>
                  <thead>
                    <tr>
                      <th>Assignment ID</th>
                      <th>Student ID</th>
                      <th>File/Text</th>
                      <th>Grade</th>
                      <th>Feedback</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {data.map(sub => (
                      <tr key={sub.id}>
                        <td>{sub.assignmentid}</td>
                        <td>{sub.studentid}</td>
                        <td><button onClick={() => viewSubmission(sub.fileurl)} className="btn">View</button></td>
                        <td>{sub.grade}</td>
                        <td>{sub.feedback}</td>
                        <td>
                          {user.role === 'instructor' && <button onClick={() => startGrading(sub)} className="btn">Grade</button>}
                          {user.role === 'student' && sub.studentid === user.id && (
                            <>
                              <button onClick={() => startEdit(sub)} className="btn">Edit</button>
                              <button onClick={() => confirmDelete(sub, 'submissions')} className="btn" style={{ background: '#e53e3e' }}>Delete</button>
                            </>
                          )}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>

                {showForm && (
                  <>
                    <h3>Edit Submission</h3>
                    <form onSubmit={(e) => { e.preventDefault(); handleCreateOrUpdate('submissions'); }}>
                      <textarea name="fileurl" value={formData.fileurl} onChange={handleFormChange} placeholder="Update submission text" required style={{ display: 'block', margin: '10px 0', padding: '10px', width: '100%', height: '150px' }} />
                      <button type="submit" className="btn">Save</button>
                      <button type="button" onClick={() => setShowForm(false)} className="btn" style={{ background: '#718096' }}>Cancel</button>
                    </form>
                  </>
                )}
              </>
            )}

            {/* Instructors Page (Admin) */}
            {page === 'instructors' && user.role === 'admin' && (
              <>
                <h2>Manage Instructors</h2>
                <button onClick={() => { setShowForm(true); setFormData(getEmptyForm('instructors')); }} className="btn">Add Instructor & Course</button>
                <table>
                  <thead>
                    <tr>
                      <th>Name</th>
                      <th>Email</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {data.map(inst => (
                      <tr key={inst.id}>
                        <td>{inst.name}</td>
                        <td>{inst.email}</td>
                        <td>
                          <button onClick={() => startEdit(inst)} className="btn">Edit</button>
                          <button onClick={() => confirmDelete(inst, 'users')} className="btn" style={{ background: '#e53e3e' }}>Delete</button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>

                {showForm && (
                  <>
                    <h3>{editingItem ? 'Edit Instructor' : 'Add Instructor & Assign Course'}</h3>
                    <form onSubmit={(e) => { e.preventDefault(); editingItem ? handleCreateOrUpdate('users') : handleAdminAddInstructor(); }}>
                      <input name="name" value={formData.name} onChange={handleFormChange} placeholder="Name" required style={{ display: 'block', margin: '10px 0', padding: '10px', width: '100%' }} />
                      <input name="email" value={formData.email} onChange={handleFormChange} placeholder="Email" required style={{ display: 'block', margin: '10px 0', padding: '10px', width: '100%' }} />
                      {!editingItem && (
                        <>
                          <input name="courseTitle" value={formData.courseTitle} onChange={handleFormChange} placeholder="Course Title" required style={{ display: 'block', margin: '10px 0', padding: '10px', width: '100%' }} />
                          <textarea name="courseDescription" value={formData.courseDescription} onChange={handleFormChange} placeholder="Course Description" style={{ display: 'block', margin: '10px 0', padding: '10px', width: '100%' }} />
                          <textarea name="courseSyllabus" value={formData.courseSyllabus} onChange={handleFormChange} placeholder="Course Syllabus" style={{ display: 'block', margin: '10px 0', padding: '10px', width: '100%' }} />
                        </>
                      )}
                      <button type="submit" className="btn">Save</button>
                      <button type="button" onClick={() => setShowForm(false)} className="btn" style={{ background: '#718096' }}>Cancel</button>
                    </form>
                  </>
                )}
              </>
            )}

            {/* Grade Modal */}
            {showGradeModal && (
              <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', background: 'rgba(0,0,0,0.7)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 2000 }}>
                <div style={{ background: 'white', padding: '30px', borderRadius: '12px', maxWidth: '500px', width: '90%' }}>
                  <h3>Grade Submission</h3>
                  <form onSubmit={(e) => { e.preventDefault(); submitGrade(); }}>
                    <input
                      type="number"
                      value={gradeValue}
                      onChange={(e) => setGradeValue(e.target.value)}
                      placeholder="Grade (0-100)"
                      style={{ display: 'block', margin: '10px 0', padding: '10px', width: '100%' }}
                    />
                    <textarea
                      value={feedbackText}
                      onChange={(e) => setFeedbackText(e.target.value)}
                      placeholder="Feedback"
                      style={{ display: 'block', margin: '10px 0', padding: '10px', width: '100%', height: '100px' }}
                    />
                    <div style={{ marginTop: '20px' }}>
                      <button type="submit" style={{ padding: '10px 20px', background: '#48bb78', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', marginRight: '10px' }}>Submit Grade</button>
                      <button type="button" onClick={() => { setShowGradeModal(false); setSubmissionToGrade(null); setGradeValue(''); setFeedbackText(''); }} style={{ padding: '10px 20px', background: '#718096', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>Cancel</button>
                    </div>
                  </form>
                </div>
              </div>
            )}

            {/* View Submission Text Modal */}
            {showFileModal && (
              <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', background: 'rgba(0,0,0,0.7)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 2000 }}>
                <div style={{ background: 'white', padding: '30px', borderRadius: '12px', maxWidth: '800px', width: '90%', maxHeight: '80vh', overflowY: 'auto' }}>
                  <h3 style={{ margin: '0 0 20px' }}>Submission Text</h3>
                  <p style={{ whiteSpace: 'pre-wrap', background: '#f7fafc', padding: '20px', borderRadius: '8px', minHeight: '200px' }}>
                    {currentSubmissionText || 'No content'}
                  </p>
                  <button onClick={() => setShowFileModal(false)} style={{ padding: '10px 20px', background: '#667eea', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>
                    Close
                  </button>
                </div>
              </div>
            )}

            {/* Confirm Delete Modal */}
            {showConfirmDelete && (
              <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', background: 'rgba(0,0,0,0.7)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 2000 }}>
                <div style={{ background: 'white', padding: '30px', borderRadius: '12px', textAlign: 'center' }}>
                  <h3>Are you sure you want to delete?</h3>
                  <div style={{ marginTop: '20px' }}>
                    <button onClick={handleDelete} style={{ marginRight: '10px', padding: '10px 20px', background: '#e53e3e', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>Yes, Delete</button>
                    <button onClick={() => { setShowConfirmDelete(false); setItemToDelete(null); setDeleteBase(''); }} style={{ padding: '10px 20px', background: '#718096', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>Cancel</button>
                  </div>
                </div>
              </div>
            )}

            {/* AI Chat Modal */}
            {showChat && (
              <div style={{ position: 'fixed', bottom: 0, right: 0, width: '400px', height: '500px', background: 'white', color: 'black', borderRadius: '12px 12px 0 0', boxShadow: '0 -4px 20px rgba(0,0,0,0.3)', zIndex: 1000 }}>
                <div style={{ background: '#667eea', color: 'white', padding: '15px', borderRadius: '12px 12px 0 0', display: 'flex', justifyContent: 'space-between' }}>
                  <h3 style={{ margin: 0 }}>AI Assistant</h3>
                  <button onClick={() => setShowChat(false)} style={{ background: 'none', border: 'none', color: 'white', cursor: 'pointer' }}>X</button>
                </div>
                <div style={{ height: '350px', overflowY: 'auto', padding: '15px' }}>
                  {chatMessages.map((msg, idx) => (
                    <div key={idx} style={{ textAlign: msg.sender === 'user' ? 'right' : 'left', marginBottom: '10px' }}>
                      <span style={{ background: msg.sender === 'user' ? '#4facfe' : '#e2e8f0', color: msg.sender === 'user' ? 'white' : 'black', padding: '10px', borderRadius: '12px', display: 'inline-block' }}>
                        {msg.text}
                      </span>
                    </div>
                  ))}
                  {chatLoading && <div style={{ textAlign: 'left' }}><span style={{ background: '#e2e8f0', padding: '10px', borderRadius: '12px' }}>Typing...</span></div>}
                  <div ref={chatEndRef} />
                </div>
                <form onSubmit={(e) => { e.preventDefault(); sendChatMessage(); }} style={{ display: 'flex', padding: '15px', borderTop: '1px solid #ddd' }}>
                  <input value={chatInput} onChange={(e) => setChatInput(e.target.value)} placeholder="Ask about the portal..." style={{ flex: 1, padding: '10px', borderRadius: '20px', border: '1px solid #ddd', marginRight: '10px' }} />
                  <button type="submit" style={{ padding: '10px 20px', background: '#4facfe', color: 'white', border: 'none', borderRadius: '20px' }}>Send</button>
                </form>
              </div>
            )}

          </div>
        </main>
        <footer style={{ textAlign: 'center', padding: '30px', color: 'white', background: 'rgba(0,0,0,0.3)', marginTop: '50px' }}>
          <h3 style={{ margin: '0 0 10px' }}>Student Portal © 2025</h3>
          <p style={{ margin: 0, opacity: 0.9 }}>Nikko Manuel - Marlon Chipa Learning Management System</p>
        </footer>
      </>
    </div>
  );
}

export default App;
